 ax.imshow(mat,cmap='RdBu_r',vmin=-1,vmax=1);ax.set_xticks(range(3),['Myeloid','Stromal','Mural']);ax.set_yticks(range(3),['Myeloid','Stromal','Mural']);ax.set_title(group+' n='+str(len(ids)))
