fig.suptitle('GSE162694: frozen broad signatures; within-stratum descriptive Spearman rho');fig.tight_layout(rect=[0,0,1,.94]);fig.savefig(O/'independent_signature_correlations.png',dpi=180);plt.close(fig);pd.DataFrame(rows).to_csv(O/'within_group_correlations.tsv',sep='\t',index=False);v={'status':'completed','samples':143,'features':31683,'mapped_symbols':int(names.notna().sum()),'unmapped_Ensembl_retained':int(names.isna().sum()),'groups':expected,'all_IDs_exact':True,'scores_finite':True,'correlations':18,'rank_based_independent_check':True};(O/'validation.json').write_text(json.dumps(v,indent=2));print(json.dumps(v))
